    K_EST = 1.00
    KP = 0.35
    KI = 0.008
    KA = 0.004
    TF_F = 15.0
    TF_S = 80.0
    TR = 140.0
    U_MIN = 0.0
    U_MAX = 0.65
    I_MIN = -0.25
    I_MAX = 0.25
    FF_MIN = 0.12
    FF_MAX = 0.60
    INT_GATE = 0.15
    FF_GATE = 0.06
    try:
