    if dt < 0.05:
        dt = 0.05
    if dt > 10.0:
        dt = 10.0
    if target < 0.0:
        target = 0.0
    if target > 1.0:
        target = 1.0
    if y < 0.0:
        y = 0.0
    if y > 1.0:
        y = 1.0
    if not isinstance(state, dict):
        state = {}
    try:
        yf_prev = float(state.get("yf", y))
    except Exception:
        yf_prev = y
    try:
        ys_prev = float(state.get("ys", y))
    except Exception:
        ys_prev = y
    try:
        integ_prev = float(state.get("integ", 0.0))
    except Exception:
        integ_prev = 0.0
    try:
        uff_prev = float(state.get("uff", -99.0))
    except Exception:
        uff_prev = -99.0
    try:
        u_prev = float(state.get("u_prev", -1.0))
    except Exception:
        u_prev = -1.0
    try:
        t_prev = float(state.get("t", -1.0))
    except Exception:
        t_prev = -1.0
    try:
        y0_prev = float(state.get("y0", y))
    except Exception:
        y0_prev = y
    try:
        targ0_prev = float(state.get("targ0", target))
    except Exception:
        targ0_prev = target
    if not math.isfinite(yf_prev):
        yf_prev = y
    if not math.isfinite(ys_prev):
        ys_prev = y
    if not math.isfinite(integ_prev):
        integ_prev = 0.0
    if not math.isfinite(uff_prev):
        uff_prev = -99.0
    if not math.isfinite(u_prev):
        u_prev = -1.0
    if not math.isfinite(t_prev) or t_prev < -0.5:
        first = True
        t_prev = 0.0
        y0_prev = y
        targ0_prev = target
    else:
