    if not math.isfinite(y0_prev):
        y0_prev = y
    if not math.isfinite(targ0_prev):
        targ0_prev = target
    yf_prev = _clamp(yf_prev, 0.0, 1.0)
    ys_prev = _clamp(ys_prev, 0.0, 1.0)
    y0_prev = _clamp(y0_prev, 0.0, 1.0)
    integ_prev = _clamp(integ_prev, I_MIN, I_MAX)
