    u_des_cand = _clamp(u_des_cand, U_MIN, U_MAX)
    if (u_des_cand >= U_MAX - 1e-9 and e > 0.0) or (u_des_cand <= U_MIN + 1e-9 and e < 0.0):
        integ = integ_prev
        uff = uff_prev
        u_des = uff + p_term + integ
        u_des = _clamp(u_des, U_MIN, U_MAX)
    else:
        integ = integ_cand
        uff = uff_cand
        u_des = u_des_cand
    if yf > 0.78:
        u_des = U_MIN
        if integ > 0.0:
            integ = integ - 0.02 * dt
            integ = _clamp(integ, I_MIN, I_MAX)
    elif yf > 0.72:
