            u_des = 0.12
    if u_prev < -0.5:
        u_out = u_des
    else:
        up = _clamp(u_prev, U_MIN, U_MAX)
        max_du = 0.02 * dt
        if max_du < 0.01:
            max_du = 0.01
        if max_du > 0.10:
            max_du = 0.10
        du = u_des - up
        if du > max_du:
            du = max_du
        elif du < -max_du:
            du = -max_du
        u_out = up + du
    u_out = _clamp(u_out, U_MIN, U_MAX)
    if not math.isfinite(u_out):
        u_out = ff0
    if u_out < 0.0:
        u_out = 0.0
    if u_out > 1.0:
        u_out = 1.0
